mapper.select:
SELECT *
FROM (
  SELECT t.*
  FROM CHAT_MESSAGE t
  WHERE t.CHATROOM_ID = #{roomId}

      AND t.MESSAGE_ID < #{beforeMessageId}

  ORDER BY t.MESSAGE_ID DESC
)
WHERE ROWNUM <= #{limit}
ORDER BY MESSAGE_ID ASC

mapper.update:
UPDATE CHAT_MESSAGE
   SET IS_READ = 'Y',
       READ_AT = SYSTIMESTAMP
 WHERE CHATROOM_ID = #{roomId}
   AND SENDER_ID <> #{userId}
   AND MESSAGE_ID <= #{upToMessageId}
   AND IS_READ = 'N'

mapper.select:
SELECT COUNT(*)
  FROM CHAT_MESSAGE
 WHERE CHATROOM_ID = #{roomId}
   AND SENDER_ID <> #{userId}
   AND IS_READ = 'N'
